use crate::prelude::*;

/// "Creatures you control get +1/+1": a static ability over the permanents a filter accepts,
/// read each time the layers apply ([CR 611.3a]): "A continuous effect generated by a static
/// ability isn't 'locked in'; it applies at any given moment to whatever its text
/// indicates." So a creature that enters later gets +1/+1, and one that stops being a
/// creature stops getting it. The bonus applies in layer 7c ([CR 613.4c]): "Effects and
/// counters that modify power and/or toughness (but don't set power and/or toughness to a
/// specific number or value) are applied", after the type-changing effects of layer 4 have
/// decided what is a creature.
///
/// [CR 611.3a]: https://yawgatog.com/resources/magic-rules/#R6113a
/// [CR 613.4c]: https://yawgatog.com/resources/magic-rules/#R6134c
pub static CARD: CardDef = Printed::GloriousAnthem
    .abilities(&[Ability::static_ability(&LayerSpec {
        affected: Objects::All {
            zone: Zone::Battlefield,
            filter: CREATURES_YOU_CONTROL,
        },
        condition: None,
        modifications: &[Modification::ModifyPt(1, 1)],
    })])
    .card();

